def fitdeg(d):
    cols=[]
    for i in range(d+1):
        for j in range(d+1):
            if i+j<=d: cols.append(eps**i*T**j)
    A=np.column_stack(cols)
    c,*_=np.linalg.lstsq(A,sigma,rcond=None)
    return np.mean((A@c-sigma)**2)/np.var(sigma)
for d in [2,3,4,5,6]:
    print(d, fitdeg(d))
